function insertIntersectionPoint(arr, newPt) {
	const epsilon = 1e-6;

	for (const p of arr) {
		if (dist(p.x, p.y, newPt.x, newPt.y) < epsilon) {
			return false;
		}
	}

	arr.push(newPt);
	return true;
}

// Line segment intersection algorithm
function lineSegmentIntersection(p1, p2, p3, p4) {
  var epsilon = 1e-6;

  let a1 = p2.y - p1.y;
  let b1 = p1.x - p2.x;
  let c1 = a1 * p1.x + b1 * p1.y;

  let a2 = p4.y - p3.y;
  let b2 = p3.x - p4.x;
  let c2 = a2 * p3.x + b2 * p3.y;

  let denominator = a1 * b2 - a2 * b1;

  // Handle parallel lines with epsilon tolerance
  if (Math.abs(denominator) < epsilon) {
    return null;
  }

  let intersectX = (b2 * c1 - b1 * c2) / denominator;
  let intersectY = (a1 * c2 - a2 * c1) / denominator;

  // Check if the intersection point is within both segments
  if (isPointOnSegment(intersectX, intersectY, p1, p2) &&
      isPointOnSegment(intersectX, intersectY, p3, p4)) {
    return { x: intersectX, y: intersectY };
  }

  return null;
}

// Check if a point is on a line segment
function isPointOnSegment(x, y, p1, p2) {
  var epsilon = 1e-6; // S mall tolerance for floating-point errors
  return (
    x >= Math.min(p1.x, p2.x) - epsilon &&
    x <= Math.max(p1.x, p2.x) + epsilon &&
    y >= Math.min(p1.y, p2.y) - epsilon &&
    y <= Math.max(p1.y, p2.y) + epsilon
  );
}

// Check if a point is inside a polygon (ray-casting algorithm)
function isPointInPolygon(x, y, polygon) {
  var epsilon = 1e-6;
  let isInside = false;

  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const xi = polygon[i].x, yi = polygon[i].y;
    const xj = polygon[j].x, yj = polygon[j].y;

    const intersect = ((yi > y + epsilon) !== (yj > y + epsilon)) &&
      (x < (xj - xi) * (y - yi) / (yj - yi + epsilon) + xi);

    if (intersect) isInside = !isInside;
  }

  return isInside;
}

