function getBoundingBox(area, num = 100) {
	let minx = Infinity, miny = Infinity, maxx = -Infinity, maxy = -Infinity;
	for (const p of area) {
		if (p.x < minx) minx = p.x; 
		if (p.x > maxx) maxx = p.x; 
		if (p.y < miny) miny = p.y; 
		if (p.y > maxy) maxy = p.y; 
	}
	return {x: minx, y: miny, w: maxx-minx, h: maxy-miny};
}


function addCircle(x, y, r, circles, polygon, mar = 0) {
	const newCircle = {x, y, r};

	// Check if the new circle overlaps with existing circles
	if (overlapsCircles(newCircle, circles, mar)) return false;

	// Check if the new circle fits entirely within the polygon
	// if (!circleFitsInArea(newCircle, polygon)) return false;

	// If both checks pass, add the circle to the array
	circles.push(newCircle);
	return true;
}

function overlapsCircles(newCircle, circles, mar) {
	for (let circle of circles) {
		// Calculate distance between circle centers
		var dx = newCircle.x - circle.x;
		var dy = newCircle.y - circle.y;
		const distance = Math.sqrt(dx * dx + dy * dy);

		// If distance is less than sum of radii, circles overlap
		if (distance < newCircle.r + circle.r + mar) {
			return true;
		}
	}
	// No overlaps found
	return false;
}

function circleFitsInArea(circle, polygon) {
	// First check if center is inside polygon
	if (!isPointInPolygon(circle.x, circle.y, polygon)) {
		return false;
	}

	// Then check if any point on circle edge falls outside polygon
	// We'll check several points around the circle
	const numPoints = 16; // Number of points to check on circle circumference
	for (let i = 0; i < numPoints; i++) {
		const angle = (i / numPoints) * 2 * Math.PI;
		var px = circle.x + circle.r * Math.cos(angle);
		var py = circle.y + circle.r * Math.sin(angle);

		if (!isPointInPolygon(px, py, polygon)) {
			return false;
		}
	}

	return true;
}

